import{C as e,E as t,I as n,M as r,R as i,S as a,b as o,g as s,r as c,x as l,y as u}from"#entry";import{t as d}from"./CCrr1OGQ.js";import{t as f}from"./j-IC3ihx.js";import{t as p}from"./DSb9wSJa.js";import{t as m}from"./DKx5xoX8.js";var h={class:`shell content-section narrow-content legal-copy`},g={class:`breadcrumb`,"aria-label":`Migas de pan`},_={"aria-current":`page`},v={class:`page-header`},y={class:`article-meta`},b=e({__name:`como-comprar-iphone-mayorista-para-revender`,setup(e){let b=f.find(e=>e.slug===`como-comprar-iphone-mayorista-para-revender`);return m({title:b.title,description:b.excerpt,path:`/mayorista/blog/${b.slug}`}),p([{name:`Inicio`,path:`/mayorista`},{name:`Guías`,path:`/mayorista/blog`},{name:b.title,path:`/mayorista/blog/${b.slug}`}]),(e,f)=>{let p=c,m=d;return t(),u(`div`,h,[s(`nav`,g,[a(p,{to:`/mayorista`},{default:r(()=>[...f[0]||=[l(`Inicio`,-1)]]),_:1}),f[2]||=s(`span`,{"aria-hidden":`true`},`/`,-1),a(p,{to:`/mayorista/blog`},{default:r(()=>[...f[1]||=[l(`Guías`,-1)]]),_:1}),f[3]||=s(`span`,{"aria-hidden":`true`},`/`,-1),s(`span`,_,i(n(b).title),1)]),s(`header`,v,[s(`h1`,null,i(n(b).title),1)]),s(`p`,y,[s(`span`,null,i(n(b).readingMinutes)+` min de lectura`,1)]),f[5]||=o(`<p> El iPhone es, casi siempre, el equipo que más rápido se vende en un local de celulares o en una cuenta de reventa por Instagram o Mercado Libre. Pero comprarlo mal —al proveedor equivocado, sin comparar condiciones, sin entender los tiempos— puede convertir un buen producto en un dolor de cabeza. Esta guía repasa lo que conviene tener resuelto antes de hacer tu primer pedido mayorista de iPhone. </p><h2>1. Definí qué modelos tienen salida en tu zona</h2><p> No hace falta empezar comprando el modelo más nuevo y más caro. Un error común de quien arranca a revender es inmovilizar capital en el equipo top de gama cuando su público real busca algo más accesible. Antes de pedir precio, pensá: ¿tu cliente típico busca el último modelo, o un equipo un año o dos más viejo a mejor precio? Las dos estrategias funcionan, pero conviene elegir una antes de comprar. </p><h2>2. Consultá precio y disponibilidad actualizada, no un precio de lista</h2><p> El precio del iPhone en dólares se mueve seguido, y en Argentina eso se traduce directo al precio en pesos. Cualquier proveedor serio te va a pedir que confirmes precio el mismo día que vas a pagar, no una semana antes. Desconfiá de quien te asegura un precio &quot;fijo&quot; por varias semanas sin condiciones. </p><h2>3. Preguntá por la modalidad de entrega antes de pagar</h2><p> Si el proveedor tiene un local u oficina física donde podés retirar el pedido, es una señal de seriedad: significa que existe una operación real detrás, no solo un perfil de redes sociales. Si estás en otra provincia, preguntá cómo se coordina el envío y quién se hace cargo del seguro del paquete. </p><h2>4. Entendé las condiciones de garantía antes de comprar, no después</h2><p> Las condiciones de garantía varían según el proveedor y el estado del equipo (nuevo, sellado, usado reacondicionado). Pedilas por escrito antes de pagar, no las des por sentado. Un proveedor mayorista serio te las va a explicar sin vueltas. </p><h2>5. Empezá con un pedido chico para conocer al proveedor</h2><p> Antes de comprometer un volumen grande, hacé un primer pedido más chico. Te sirve para evaluar tiempos de entrega, calidad de la comunicación y si el equipo llega tal cual se describió. Un buen proveedor no tiene problema en que empieces así. </p><p> En Nexo Imports trabajamos con iPhone para comercios y revendedores en toda Argentina, con atención directa por WhatsApp y oficinas de retiro en Caballito y Belgrano. </p>`,12),a(m,{label:`Consultar por iPhone mayorista`,message:`Hola Nexo Imports, leí la guía de compra mayorista y quiero consultar disponibilidad de iPhone.`}),s(`p`,null,[a(p,{to:`/mayorista/iphone-mayorista`},{default:r(()=>[...f[4]||=[l(`Ver más sobre iPhone mayorista ↗`,-1)]]),_:1})])])}}});export{b as default};